#!/bin/sh\nset -eu\n# Railway volumes arrive root-owned. Initialize only the configured mount, then drop privileges.\nif [ "$(id -u)" = 0 ]; then\n    [ "${APP_MEDIA_DIR:-}" = /app/media ] || { echo 'Expected APP_MEDIA_DIR=/app/media' >&2; exit 1; }\n    [ ! -L /app/media ] || { echo 'Media mount cannot be a symlink' >&2; exit 1; }\n    mkdir -p /app/media\n    chown 10001:10001 /app/media\n    chmod 700 /app/media\n    exec su -s /bin/sh freshmall -c 'exec /opt/java/openjdk/bin/java -XX:MaxRAMPercentage=65.0 -XX:+ExitOnOutOfMemoryError -jar /app/app.jar'\nfi\nexec /opt/java/openjdk/bin/java -XX:MaxRAMPercentage=65.0 -XX:+ExitOnOutOfMemoryError -jar /app/app.jar\n
